-- Disposable PostgreSQL baseline approximating the legacy access grants/policies
-- observed in Supabase. This file runs only inside the ephemeral GitHub Actions DB.
DO $$ BEGIN CREATE ROLE anon NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticated NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE service_role NOLOGIN BYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE SCHEMA IF NOT EXISTS auth;
CREATE TABLE IF NOT EXISTS auth.users (id uuid PRIMARY KEY);
CREATE OR REPLACE FUNCTION auth.uid()
RETURNS uuid
LANGUAGE sql
STABLE
AS $$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;

CREATE TABLE public.containers (
  id text PRIMARY KEY,
  data jsonb NOT NULL DEFAULT '[]'::jsonb,
  updated_at timestamptz DEFAULT now()
);
CREATE TABLE public.user_roles (
  user_id uuid PRIMARY KEY,
  role text NOT NULL DEFAULT 'Viewer',
  access_code text UNIQUE,
  username text
);
CREATE TABLE public.audit_logs (
  id text PRIMARY KEY,
  "timestamp" timestamptz DEFAULT now(),
  operator text,
  action text,
  "containerNo" text,
  field text,
  "oldVal" text,
  "newVal" text
);
CREATE TABLE public.staff_profiles (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  display_name text NOT NULL,
  role text NOT NULL CHECK (role IN ('Admin','Editor','Viewer','Operator')),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.customer_tracking_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token_hash text NOT NULL UNIQUE,
  container_no text NOT NULL,
  label text,
  expires_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  last_used_at timestamptz
);
CREATE TABLE public.edge_rate_limit_buckets (
  bucket_key text PRIMARY KEY,
  window_started_at timestamptz NOT NULL,
  request_count integer NOT NULL CHECK (request_count > 0),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.igm_hbl_details (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  hbl_no text,
  mbl_no text,
  container_no text,
  total_package numeric,
  gross_weight numeric,
  line_number integer,
  subline_number integer,
  igm_no text
);
CREATE TABLE public.containers_backup_20260926 (
  id text,
  data jsonb,
  updated_at timestamptz
);

ALTER TABLE public.containers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.staff_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_tracking_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.edge_rate_limit_buckets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.igm_hbl_details ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.containers_backup_20260926 ENABLE ROW LEVEL SECURITY;

-- Recreate the wide legacy grants and policies discovered on the connected DB.
GRANT ALL ON public.containers, public.user_roles, public.audit_logs,
  public.staff_profiles, public.customer_tracking_tokens,
  public.igm_hbl_details, public.containers_backup_20260926
TO PUBLIC, anon, authenticated;

CREATE POLICY "Allow all public access" ON public.containers FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/update for containers" ON public.containers FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow delete for Admins only" ON public.containers FOR DELETE USING (true);
CREATE POLICY "Allow inserts for Editors and Admins" ON public.containers FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow read access for authenticated users" ON public.containers FOR SELECT USING (true);
CREATE POLICY "Allow updates for Editors and Admins" ON public.containers FOR UPDATE USING (true) WITH CHECK (true);

CREATE POLICY "Allow public access code verification" ON public.user_roles FOR SELECT USING (true);
CREATE POLICY "Allow public read of user_roles" ON public.user_roles FOR SELECT USING (true);
CREATE POLICY "Users can read own role" ON public.user_roles FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Allow delete for Admins only" ON public.audit_logs FOR DELETE USING (true);
CREATE POLICY "Allow insert for authenticated" ON public.audit_logs FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Allow public access for audit_logs" ON public.audit_logs FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow read for authenticated" ON public.audit_logs FOR SELECT USING (auth.uid() IS NOT NULL);

CREATE POLICY staff_profiles_select_self ON public.staff_profiles
  FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()) AND is_active = true);

CREATE OR REPLACE FUNCTION public.get_customer_igm_bundle(p_container text)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER
AS $$ SELECT '{}'::jsonb $$;
CREATE OR REPLACE FUNCTION public.get_igm_hbl_detail(p_hbl text)
RETURNS SETOF public.igm_hbl_details LANGUAGE sql STABLE SECURITY DEFINER
AS $$ SELECT * FROM public.igm_hbl_details WHERE false $$;
CREATE OR REPLACE FUNCTION public.get_igm_hbls_for_container(p_container text)
RETURNS SETOF public.igm_hbl_details LANGUAGE sql STABLE SECURITY DEFINER
AS $$ SELECT * FROM public.igm_hbl_details WHERE false $$;
CREATE OR REPLACE FUNCTION public.get_igm_hbls_for_shipment(p_mbl text, p_container text)
RETURNS SETOF public.igm_hbl_details LANGUAGE sql STABLE SECURITY DEFINER
AS $$ SELECT * FROM public.igm_hbl_details WHERE false $$;
CREATE OR REPLACE FUNCTION public.import_igm_hbl_rows(p_access_code text, p_rows jsonb)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER
AS $$ SELECT '{}'::jsonb $$;
CREATE OR REPLACE FUNCTION public.import_igm_hbl_rows(p_user_id uuid, p_rows jsonb)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER
AS $$ SELECT '{}'::jsonb $$;
CREATE OR REPLACE FUNCTION public.search_customer_igm(p_query text)
RETURNS SETOF public.igm_hbl_details LANGUAGE sql STABLE SECURITY DEFINER
AS $$ SELECT * FROM public.igm_hbl_details WHERE false $$;
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER
AS $$ BEGIN NULL; END; $$;

-- Simulate inherited legacy execute access for the functions reported by advisors.
GRANT EXECUTE ON FUNCTION public.get_customer_igm_bundle(text),
  public.get_igm_hbl_detail(text),
  public.get_igm_hbls_for_container(text),
  public.get_igm_hbls_for_shipment(text,text),
  public.import_igm_hbl_rows(text,jsonb),
  public.import_igm_hbl_rows(uuid,jsonb),
  public.search_customer_igm(text),
  public.rls_auto_enable()
TO PUBLIC, anon, authenticated;
